import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

const ProfilePage = () => {
  const navigate = useNavigate();

  const [profile, setProfile] = useState(null);
  const [tempProfile, setTempProfile] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [successMsg, setSuccessMsg] = useState("");

  // Fetch profile data from the server
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      setError("No authentication token found. Please log in.");
      navigate("/login");
      return;
    }
    fetch("http://localhost:5001/api/user/profile", {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      }
    })
      .then((res) =>
        res.ok ? res.json() : Promise.reject("Failed to fetch profile")
      )
      .then((data) => {
        setProfile(data);
        setTempProfile(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching profile:", err);
        setError("Failed to load profile");
        setLoading(false);
      });
  }, [navigate]);

  // Handle file upload for profile photo using the provided upload style
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const token = localStorage.getItem("token");
    const formData = new FormData();
    formData.append("profilePhoto", file);
    formData.append("userId", profile._id);
    fetch("http://localhost:5001/api/user/uploadProfile", {
      method: "POST",
      body: formData,
      headers: {
        Authorization: `Bearer ${token}`
      }
    })
      .then((res) =>
        res.ok ? res.json() : Promise.reject("Failed to upload file")
      )
      .then((data) => {
        // Assume the API returns { image: "url-to-uploaded-image" }
        setTempProfile((prev) => ({ ...prev, image: data.image }));
      })
      .catch((err) => {
        console.error("Error uploading file:", err);
      });
  };

  // Handle changes to form fields during editing
  const handleChange = (field, value) => {
    setTempProfile((prev) => ({ ...prev, [field]: value }));
  };

  // When user presses Enter in any input, trigger the save update
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSave();
    }
  };

  // Save changes: call the PUT endpoint so that the updated fields are reflected immediately
  const handleSave = () => {
    const token = localStorage.getItem("token");
    if (!token) {
      console.error("Authentication token missing.");
      return;
    }
    fetch("http://localhost:5001/api/user/profile", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify(tempProfile)
    })
      .then((res) =>
        res.ok ? res.json() : Promise.reject("Failed to update profile")
      )
      .then((updatedProfile) => {
        setProfile(updatedProfile);
        setTempProfile(updatedProfile);
        setIsEditing(false);
        setSuccessMsg("Profile updated successfully!");
        setTimeout(() => setSuccessMsg(""), 3000);
      })
      .catch((err) => {
        console.error("Error updating profile:", err);
        setError("Failed to update profile");
      });
  };

  if (loading) return <p>Loading...</p>;
  if (error) return <p style={{ color: "red" }}>{error}</p>;

  return (
    <div>
      <h1>Profile Page</h1>
      {/* Display Profile Information */}
      <div>
        <img src={profile.image || "default-user.png"} alt="User" width="100" />
        <p>Name: {profile.name}</p>
        <p>Bio: {profile.bio}</p>
        <p>
          Skills:{" "}
          {profile.skills && profile.skills.length
            ? profile.skills.join(", ")
            : "No skills listed"}
        </p>
        <p>Rating: {profile.rating || "N/A"}</p>
        <button onClick={() => setIsEditing(true)}>Edit</button>
        {successMsg && <p style={{ color: "green" }}>{successMsg}</p>}
      </div>

      {/* Edit Form */}
      {isEditing && (
        <div>
          <h2>Edit Profile</h2>
          <h3>Attachments</h3>
          <div className="file-upload">
            <label className="upload-area">
              <input type="file" onChange={handleFileUpload} />
              <div className="upload-content">
                <svg viewBox="0 0 24 24" width="48" height="48">
                  <path
                    fill="currentColor"
                    d="M14,13V17H10V13H7L12,8L17,13H14M19.35,10.03C18.67,6.59 15.64,4 12,4C9.11,4 6.6,5.64 5.35,8.03C2.34,8.36 0,10.9 0,14A6,6 0 0,0 6,20H19A5,5 0 0,0 24,15C24,12.36 21.95,10.22 19.35,10.03Z"
                  />
                </svg>
                <p>Drag files here or click to upload</p>
              </div>
            </label>
          </div>
          <div>
            <label>Change Password:</label>
            <input
              type="password"
              value={tempProfile.password || ""}
              onChange={(e) => handleChange("password", e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Enter new password (leave blank if unchanged)"
            />
          </div>
          <div>
            <label>Bio:</label>
            <textarea
              value={tempProfile.bio || ""}
              onChange={(e) => handleChange("bio", e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Tell us about yourself"
            />
          </div>
          <div>
            <label>Skills (comma separated):</label>
            <input
              type="text"
              value={tempProfile.skills ? tempProfile.skills.join(", ") : ""}
              onChange={(e) =>
                handleChange(
                  "skills",
                  e.target.value.split(",").map((s) => s.trim())
                )
              }
              onKeyDown={handleKeyDown}
              placeholder="Enter skills"
            />
          </div>
          <button onClick={handleSave}>Save Changes</button>
          <button onClick={() => setIsEditing(false)}>Cancel</button>
        </div>
      )}
    </div>
  );
};

export default ProfilePage;
